# Code generated by Claude
"""
Compares the left and the right arm's pilot maps (bin 0, forward) of experiments/reach_map_pilot.py: the right map should be close to the left map mirrored about the robot's centre plane.

    python experiments/reach_map_mirror_check.py [--dir data/reach_map_pilot] [--bin 0]

Reports the voxel and cube counts, the volumes, the overlap (intersection over union) of the mirrored left map with the right one at voxel and cube level, how far from the other map's surface the
differing voxels lie, the holes of each map, and, for the current staging stance, how far each arm can reach across the body at the stance's forward distance and height (the right arm has to
reach 28 cm to its left of its shoulder there, the left arm 22 cm to its left). Pure numpy: no simulation.
"""

import argparse
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

import numpy as np  # noqa: E402
from scipy import ndimage  # noqa: E402

from src.reach_map import cubes_from_voxels, enclosed_unreached  # noqa: E402
from src.task_config import GRASP_MAP_CFG as C  # noqa: E402


def load(path):
    z = np.load(path)
    shape = tuple(int(v) for v in z["shape"])
    reached = np.unpackbits(z["reached"])[:int(np.prod(shape))].reshape(shape).astype(bool)
    return reached, z["origin"]


def voxel_keys(reached, origin, mirror):
    """Integer voxel coordinates in the shoulder frame (0 = the voxel from 0 to one voxel edge), optionally mirrored in y, as one int64 key per reached voxel."""
    ijk = np.argwhere(reached) + np.round(origin / C["voxel"]).astype(int)
    if mirror:
        ijk[:, 1] = -ijk[:, 1] - 1
    return (ijk[:, 0] + 2000) * 4_000_000 + (ijk[:, 1] + 2000) * 2000 + (ijk[:, 2] + 2000), ijk


def main(args):
    d = Path(args.dir)
    L, oL = load(d / f"left_bin{args.bin}.npz")
    R, oR = load(d / f"right_bin{args.bin}.npz")
    v = C["voxel"]
    for name, M, o in (("left", L, oL), ("right", R, oR)):
        ijk = np.argwhere(M) + np.round(o / v).astype(int)
        cen = (ijk + 0.5) * v
        cubes = cubes_from_voxels(M)
        enc, n_p = enclosed_unreached(M)
        print(f"{name}: {int(M.sum()):,} voxels ({M.sum() * v ** 3:.3f} m^3), {int(cubes.sum()):,} cubes, bounding box x [{cen[:, 0].min():.2f}, {cen[:, 0].max():.2f}] y [{cen[:, 1].min():.2f}, {cen[:, 1].max():.2f}] "
              f"z [{cen[:, 2].min():.2f}, {cen[:, 2].max():.2f}] m, centroid {cen.mean(axis=0).round(3)}, enclosed unreached {int(enc.sum()):,} voxels in {n_p} pockets")
    kL, ijkL = voxel_keys(L, oL, True)
    kR, ijkR = voxel_keys(R, oR, False)
    both = np.intersect1d(kL, kR)
    union = len(kL) + len(kR) - len(both)
    print(f"mirrored left vs right, voxel level: intersection {len(both):,}, union {union:,}, IoU {len(both) / union:.4f}; only in the mirrored left {len(kL) - len(both):,}, only in the right {len(kR) - len(both):,}")
    # how far from the other map's surface do the differing voxels lie
    lo = np.minimum(ijkL.min(axis=0), ijkR.min(axis=0)) - 3
    hi = np.maximum(ijkL.max(axis=0), ijkR.max(axis=0)) + 3
    for name, mine_ijk, mine_k, other_ijk, other_k in (("mirrored left", ijkL, kL, ijkR, kR), ("right", ijkR, kR, ijkL, kL)):
        grid = np.zeros(tuple(hi - lo + 1), bool)
        grid[tuple((other_ijk - lo).T)] = True
        dist = ndimage.distance_transform_edt(~grid)                        # voxels from each voxel to the other map
        sel = ~np.isin(mine_k, other_k)
        dd = dist[tuple((mine_ijk[sel] - lo).T)]
        print(f"  {name}-only voxels: {int(sel.sum()):,}; distance to the other map's nearest voxel: median {np.median(dd) * v * 1000:.1f} mm, 95th percentile {np.percentile(dd, 95) * v * 1000:.1f} mm, "
              f"largest {dd.max() * v * 1000:.1f} mm")
    cL, cR = cubes_from_voxels(L), cubes_from_voxels(R)
    kcL = np.argwhere(cL) + np.round(oL / C["cube"]).astype(int)
    kcL[:, 1] = -kcL[:, 1] - 1
    kcR = np.argwhere(cR) + np.round(oR / C["cube"]).astype(int)
    enc = lambda a: (a[:, 0] + 500) * 1_000_000 + (a[:, 1] + 500) * 1000 + (a[:, 2] + 500)
    bc = np.intersect1d(enc(kcL), enc(kcR))
    print(f"mirrored left vs right, cube level: IoU {len(bc) / (len(kcL) + len(kcR) - len(bc)):.4f} ({len(kcL):,} and {len(kcR):,} cubes)")
    # reach across the body at the staging stance's forward distance and height
    print("\nacross-the-body reach at the stance (forward 0.561 m, height -0.20 m below the shoulder): reachable lateral range y (m, shoulder frame; + is the robot's left) of the voxels in a 1 cm thick slice")
    for name, M, o in (("left", L, oL), ("right", R, oR)):
        ijk = np.argwhere(M) + np.round(o / v).astype(int)
        cen = (ijk + 0.5) * v
        sl = cen[(np.abs(cen[:, 0] - 0.561) < 0.005) & (np.abs(cen[:, 2] + 0.20) < 0.01)]
        print(f"  {name}: y from {sl[:, 1].min():+.3f} to {sl[:, 1].max():+.3f} m ({len(sl)} voxels)" if len(sl) else f"  {name}: nothing reachable in that slice")
    print("  the stance needs: left arm y = +0.219 m, right arm y = +0.281 m (the beaker is 25 cm left of the robot's centre line and the shoulders are at y = +-0.031 m)")


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("--dir", default=str(PROJECT_ROOT / "data" / "reach_map_pilot"))
    ap.add_argument("--bin", type=int, default=0)
    main(ap.parse_args())
